1	/**
2	 * @module features/tv-dashboard/model/types
3	 *
4	 * Tipos de domínio do Dashboard de Crise (painel TV `/tv`).
5	 * Spec: `.harness/spec/dashboard-tv-crise/spec.md`.
6	 */
7	
8	/**
9	 * Canal de origem do dado de venda de uma unidade.
10	 *
11	 * - `degust-live`: lojas integradas ao POS Degust (flash-vendas ao vivo).
12	 *   O conjunto de lojas vem da tabela `degust_stores` em runtime (hoje:
13	 *   Lago Sul, Águas Claras, BSB Shopping) — nunca hardcoded.
14	 * - `linx-lagged`: lojas no POS Linx sem integração live — usamos o último
15	 *   dia disponível em `historico_vendas` com selo "até DD/MM".
16	 * - `factory`: fábrica (sem venda; card de produção/expedição).
17	 */
18	export type TvSalesChannel = 'degust-live' | 'linx-lagged' | 'factory';
19	
20	/** Estado RAG (red/amber/green) de um card de unidade. */
21	export type TvRagStatus = 'ok' | 'amber' | 'red';
22	
23	/** Nível de frescor de um dado-fonte em relação ao intervalo esperado. */
24	export type TvFreshnessLevel = 'fresh' | 'stale' | 'very-stale';
25	
26	/** Severidade de uma exceção exibida na faixa inferior. */
27	export type TvExceptionSeverity = 'red' | 'amber';
28	
29	/** Tipo de exceção exibida na faixa inferior. */
30	export type TvExceptionKind =
31	  | 'stock-out'
32	  | 'stock-low'
33	  | 'no-movement'
34	  | 'stale-data';
35	
36	/** Janela de funcionamento usada no pró-rata da meta (hora local 0-24). */
37	export interface TvBusinessHours {
38	  start: number;
39	  end: number;
40	}
41	
42	/** Snapshot de vendas de uma unidade (live ou defasado). */
43	export interface TvSalesSnapshot {
44	  /** Valor vendido em R$ no dia de referência. */
45	  valor: number;
46	  /** Número de cupons/transações (null quando a fonte não informa). */
47	  cupons: number | null;
48	  /** Ticket médio em R$ (null quando a fonte não informa). */
49	  ticketMedio: number | null;
50	  /** Dia a que o dado se refere (YYYY-MM-DD). Para canal live = hoje. */
51	  dataReferencia: string;
52	  /** true quando o dado é ao vivo (flash-vendas); false = defasado. */
53	  isLive: boolean;
54	  /** Caixa aberto agora (apenas canal live; null quando não se aplica). */
55	  caixaAberto: boolean | null;
56	  /** Timestamp informado pela fonte da última atualização (ISO, ou null). */
57	  atualizadoEm: string | null;
58	}
59	
60	/** Contadores de alerta de estoque de uma unidade (apenas produtos ativos). */
61	export interface TvStockAlertSummary {
62	  /** Itens com quantidade ≤ 0 e mínimo definido (positivo). */
63	  zerados: number;
64	  /** Itens com quantidade entre 0 exclusivo e o mínimo. */
65	  abaixoMinimo: number;
66	}
67	
68	/** Item de estoque em alerta (detalhe usado na faixa de exceções). */
69	export interface TvStockAlertItem {
70	  produtoNome: string;
71	  quantidade: number;
72	  quantidadeMinima: number;
73	  /** true = zerado (vermelho); false = abaixo do mínimo (âmbar). */
74	  zerado: boolean;
75	}
76	
77	/** Heartbeat de movimentações de estoque de uma unidade no dia. */
78	export interface TvMovementSummary {
79	  /** Contagem de movimentações tipo `entrada` hoje. */
80	  entradas: number;
81	  /** Contagem de movimentações tipo `saida` hoje. */
82	  saidas: number;
83	  /** Timestamp ISO da última movimentação ("última bipagem"), ou null. */
84	  ultimaBipagem: string | null;
85	}
86	
87	/** Dados de um card de loja no grid. */
88	export interface TvStoreData {
89	  lojaId: number;
90	  nome: string;
91	  channel: TvSalesChannel;
92	  /** Vendas do dia de referência (null quando não há dado disponível). */
93	  vendas: TvSalesSnapshot | null;
94	  /** Meta do dia da semana de referência (`metas_vendas`), ou null. */
95	  metaDia: number | null;
96	  /**
97	   * % da meta. Canal live = pró-rata da janela de funcionamento;
98	   * canal defasado = % do dia COMPLETO de referência (dia já encerrado).
99	   * null quando não há meta cadastrada ou fora da janela.
100	   */
101	  pctMeta: number | null;
102	  /** Delta % vs MESMO DIA da semana anterior (nunca "ontem"), ou null. */
103	  deltaSemana: number | null;
104	  estoque: TvStockAlertSummary;
105	  movimentacao: TvMovementSummary;
106	  rag: TvRagStatus;
107	  /** Motivos legíveis (pt-BR) que levaram ao estado RAG. */
108	  ragReasons: string[];
109	}
110	
111	/** Produção agregada da fábrica num dia. */
112	export interface TvFactoryProduction {
113	  /** Dia a que a produção se refere (YYYY-MM-DD — último dia com registro). */
114	  dataReferencia: string;
115	  /** Quantidade de produtos distintos produzidos. */
116	  itens: number;
117	  /** Soma das quantidades produzidas. */
118	  totalUnidades: number;
119	}
120	
121	/** Dados do card diferenciado da fábrica. */
122	export interface TvFactoryData {
123	  lojaId: number;
124	  nome: string;
125	  /** Produção do dia (`daily_production` com loja_id NULL), ou null. */
126	  producao: TvFactoryProduction | null;
127	  /** Expedições = movimentações da fábrica hoje (saídas para lojas). */
128	  expedicoes: TvMovementSummary;
129	  estoque: TvStockAlertSummary;
130	  rag: TvRagStatus;
131	  ragReasons: string[];
132	}
133	
134	/** Uma linha da faixa de exceções. */
135	export interface TvException {
136	  /** Id estável para keys de render (ex.: `stock-out:4:BROWNIE`). */
137	  id: string;
138	  kind: TvExceptionKind;
139	  severity: TvExceptionSeverity;
140	  lojaId: number | null;
141	  lojaNome: string | null;
142	  /** Mensagem pronta para exibição (pt-BR). */
143	  message: string;
144	  produtoNome?: string;
145	  quantidade?: number;
146	  quantidadeMinima?: number;
147	}
148	
149	/** Faixa de exceções já ordenada (vermelho antes de âmbar) e limitada. */
150	export interface TvExceptionsResult {
151	  items: TvException[];
152	  /** Quantas exceções ficaram de fora do limite (para "+N itens"). */
153	  overflowCount: number;
154	  /** Total de exceções antes do corte. */
155	  totalCount: number;
156	}
157	
158	/** Resumo da rede para o hero. */
159	export interface TvNetworkSummary {
160	  /**
161	   * Vendas de HOJE em R$ — soma apenas das lojas cujo dado é de hoje
162	   * (canal live). Lojas defasadas NÃO entram para não misturar dias.
163	   */
164	  vendasHoje: number;
165	  /** Soma das metas do dia das lojas que contribuem em `vendasHoje`. */
166	  metaDia: number | null;
167	  /** % da meta pró-rata da rede (mesma regra do card de loja live). */
168	  pctMetaProRata: number | null;
169	  /** Delta % vs mesmo dia da semana passada (lojas live), ou null. */
170	  deltaSemana: number | null;
171	  /** Total de exceções vermelhas na rede (sem cap de exibição). */
172	  alertasCriticos: number;
173	  /** Quantidade de lojas com venda ao vivo. */
174	  lojasLive: number;
175	  /** Quantidade de lojas com dado defasado. */
176	  lojasDefasadas: number;
177	}
178	
179	/** Frescor de um dado-fonte. */
180	export interface TvSourceFreshness {
181	  /** Última atualização bem-sucedida (ISO), ou null se nunca carregou. */
182	  updatedAt: string | null;
183	  level: TvFreshnessLevel;
184	  /** Intervalo esperado de atualização (ms) usado na classificação. */
185	  expectedIntervalMs: number;
186	}
187	
188	/** Freshness consolidado dos dados exibidos na TV. */
189	export interface TvFreshness {
190	  /** Vendas live (polling 60s na edge `degust-pos-financial`). */
191	  vendasLive: TvSourceFreshness;
192	  /** Estoque/alertas (polling 5min + Realtime). */
193	  estoque: TvSourceFreshness;
194	  /** Momento em que o snapshot foi montado (ISO). */
195	  geradoEm: string;
196	}
