246	// ─────────────────────────────────────────────────────────────────────────────
247	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
248	// ─────────────────────────────────────────────────────────────────────────────
249	
250	function trimOneDecimal(v: number): string {
251	  const rounded = Math.round(v * 10) / 10;
252	  return rounded.toLocaleString('pt-BR', {
253	    minimumFractionDigits: 0,
254	    maximumFractionDigits: 1,
255	  });
256	}
257	
258	/**
259	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
260	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
261	 * Valores negativos preservam o sinal ("-R$ 1,2k").
262	 */
263	export function formatCompactBRL(value: number): string {
264	  const sign = value < 0 ? '-' : '';
265	  const abs = Math.abs(value);
266	  // Bump pra M quando o arredondamento em k chegaria a 1000k
267	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
268	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
269	  }
270	  if (abs >= 1_000) {
271	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
272	  }
273	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
274	}
275	
276	// ─────────────────────────────────────────────────────────────────────────────
277	// Staleness
278	// ─────────────────────────────────────────────────────────────────────────────
279	
280	/**
281	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
282	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
283	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
284	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
285	 */
286	export function classifyStaleness(
287	  lastUpdatedAt: Date | string | number | null | undefined,
288	  expectedIntervalMs: number,
289	  now: Date,
290	): TvFreshnessLevel {
291	  if (lastUpdatedAt == null) return 'very-stale';
292	  const ts = new Date(lastUpdatedAt).getTime();
293	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
294	  const age = now.getTime() - ts;
295	  if (age < 2 * expectedIntervalMs) return 'fresh';
296	  if (age < 6 * expectedIntervalMs) return 'stale';
297	  return 'very-stale';
298	}
299	
300	// ─────────────────────────────────────────────────────────────────────────────
301	// Exceções — ordenação e corte
302	// ─────────────────────────────────────────────────────────────────────────────
303	
304	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
305	const KIND_ORDER: Record<string, number> = {
306	  'stock-out': 0,
307	  'no-movement': 1,
308	  'stock-low': 2,
309	  'stale-data': 3,
310	};
311	
312	/**
313	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
314	 * (falta total, sem movimentação, abaixo do mínimo, dado stale — nesta ordem)
315	 * e por mensagem (estável), limitando a `limit` linhas com contagem do excedente.
316	 */
317	export function sortAndLimitExceptions(
318	  exceptions: TvException[],
319	  limit: number = TV_EXCEPTIONS_LIMIT,
320	): TvExceptionsResult {
321	  const sorted = [...exceptions].sort((a, b) => {
322	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
323	    if (sev !== 0) return sev;
324	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
325	    if (kind !== 0) return kind;
326	    return a.message.localeCompare(b.message, 'pt-BR');
327	  });
328	  return {
329	    items: sorted.slice(0, limit),
330	    overflowCount: Math.max(0, sorted.length - limit),
331	    totalCount: sorted.length,
332	  };
333	}
