459	/** Linha de venda live normalizada (resposta da edge `degust-pos-financial`). */
460	export interface FlashRow {
461	  loja_id: number;
462	  nome_loja: string;
463	  total_vendas: number;
464	  total_cupons: number;
465	  ticket_medio: number;
466	  caixa_aberto: boolean;
467	  ultima_atualizacao: string | null;
468	}
469	
470	/**
471	 * Corrige o `loja_id` das linhas de flash-vendas.
472	 *
473	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
474	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
475	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
476	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
477	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
478	 *
479	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
480	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
481	 * - Caso contrário → descarta (não corromper outra loja).
482	 */
483	export function remapFlashLojaIds(
484	  rows: FlashRow[],
485	  degustCodeToLoja: ReadonlyMap<number, number>,
486	  knownDegustLojaIds: ReadonlySet<number>,
487	): FlashRow[] {
488	  const out: FlashRow[] = [];
489	  for (const row of rows) {
490	    if (knownDegustLojaIds.has(row.loja_id)) {
491	      out.push(row);
492	      continue;
493	    }
494	    const mapped = degustCodeToLoja.get(row.loja_id);
495	    if (mapped != null) {
496	      out.push({ ...row, loja_id: mapped });
497	    }
498	    // não mapeável → descartado de propósito (ver TSDoc)
499	  }
500	  return out;
501	}
