503	/** Linha mínima de `degust_vendas_diarias` para o top produtos. */
504	export interface DailyProductRow {
505	  degust_nome: string;
506	  quantidade: number | null;
507	  valor_total: number | null;
508	}
509	
510	/** Produto agregado do dia (rede). */
511	export interface TvTopProduct {
512	  nome: string;
513	  quantidade: number;
514	  valor: number;
515	}
516	
517	/**
518	 * Top N produtos do dia da rede, agregando `degust_vendas_diarias` por nome.
519	 * Ranking por quantidade vendida (desempate por valor).
520	 */
521	export function topProductsFromDaily(
522	  rows: DailyProductRow[],
523	  n = 5,
524	): TvTopProduct[] {
525	  const byName = new Map<string, TvTopProduct>();
526	  for (const row of rows) {
527	    let agg = byName.get(row.degust_nome);
528	    if (!agg) {
529	      agg = { nome: row.degust_nome, quantidade: 0, valor: 0 };
530	      byName.set(row.degust_nome, agg);
531	    }
532	    agg.quantidade += row.quantidade ?? 0;
533	    agg.valor += row.valor_total ?? 0;
534	  }
535	  return [...byName.values()]
536	    .sort((a, b) => b.quantidade - a.quantidade || b.valor - a.valor)
537	    .slice(0, n);
538	}
