1	// Local ESLint plugin — MIA glass-box coverage hints.
2	//
3	// Rules:
4	//   - mia-coverage/require-data-mia-action: warn quando <Button onClick={...}>
5	//     não tem data-mia-action. Aumenta cobertura organicamente.
6	//   - mia-coverage/require-data-mia-field: warn quando <Input id=X> não tem
7	//     data-mia-field=X.
8	//   - mia-coverage/require-data-mia-filter: warn quando <SelectTrigger> dentro
9	//     de <Select> não tem data-mia-filter.
10	//
11	// Severidade WARN (não error) — informa, não bloqueia merge. Quando coverage
12	// ficar > 90%, podemos subir pra error.
13	//
14	// Doc: docs/mia/ARCHITECTURE.md (Section 12.3 — ESLint coverage rule)
15	
16	const hasJsxAttribute = (node, name) =>
17	  Array.isArray(node.attributes) && node.attributes.some((attr) =>
18	    attr.type === 'JSXAttribute' && attr.name?.name === name
19	  );
20	
21	const getJsxAttribute = (node, name) =>
22	  Array.isArray(node.attributes) ? node.attributes.find((attr) =>
23	    attr.type === 'JSXAttribute' && attr.name?.name === name
24	  ) : null;
25	
26	const tagNameOf = (node) => {
27	  if (!node?.name) return '';
28	  if (node.name.type === 'JSXIdentifier') return node.name.name;
29	  if (node.name.type === 'JSXMemberExpression') return node.name.property?.name ?? '';
30	  return '';
31	};
32	
33	const requireActionRule = {
34	  meta: {
35	    type: 'suggestion',
36	    docs: { description: 'Adicione data-mia-action em Button com onClick' },
37	    schema: [],
38	  },
39	  create(context) {
40	    return {
41	      JSXOpeningElement(node) {
42	        const tag = tagNameOf(node);
43	        // Cobre Button, button, DropdownMenuItem, MenuItem (cliques principais)
44	        if (!['Button', 'button', 'DropdownMenuItem', 'MenuItem', 'CommandItem'].includes(tag)) return;
45	        // Só warn se tiver onClick (botões sem onClick podem ser display)
46	        if (!hasJsxAttribute(node, 'onClick')) return;
47	        // Já tem data-mia-action ou data-mia-skip → ok
48	        if (hasJsxAttribute(node, 'data-mia-action')) return;
49	        if (hasJsxAttribute(node, 'data-mia-skip')) return;
50	        // asChild — vai delegar pro filho (pode ter no Link/etc)
51	        if (hasJsxAttribute(node, 'asChild')) return;
52	        context.report({
53	          node,
54	          message: `<${tag}> com onClick sem \`data-mia-action="..."\`. Adicione pra MIA glass-box poder clicar (use data-mia-skip se intencional).`,
55	        });
56	      },
57	    };
58	  },
59	};
60	
61	const requireFieldRule = {
62	  meta: {
63	    type: 'suggestion',
64	    docs: { description: 'Adicione data-mia-field em Input/Textarea' },
65	    schema: [],
66	  },
67	  create(context) {
68	    return {
69	      JSXOpeningElement(node) {
70	        const tag = tagNameOf(node);
71	        if (!['Input', 'Textarea', 'input', 'textarea'].includes(tag)) return;
72	        if (hasJsxAttribute(node, 'data-mia-field')) return;
73	        if (hasJsxAttribute(node, 'data-mia-skip')) return;
74	        // Pula inputs de busca/filtro inline (search bar do shadcn etc)
75	        const type = getJsxAttribute(node, 'type')?.value?.value;
76	        if (type === 'hidden' || type === 'file') return;
77	        // Pula sem id E sem name E sem placeholder (provavelmente decorativo)
78	        const hasId = hasJsxAttribute(node, 'id');
79	        const hasName = hasJsxAttribute(node, 'name');
80	        const hasPlaceholder = hasJsxAttribute(node, 'placeholder');
81	        if (!hasId && !hasName && !hasPlaceholder) return;
82	        context.report({
83	          node,
84	          message: `<${tag}> sem \`data-mia-field="..."\`. Adicione pra MIA glass-box poder preencher.`,
85	        });
86	      },
87	    };
88	  },
89	};
90	
91	const requireFilterRule = {
92	  meta: {
93	    type: 'suggestion',
94	    docs: { description: 'Adicione data-mia-filter em SelectTrigger' },
95	    schema: [],
96	  },
97	  create(context) {
98	    return {
99	      JSXOpeningElement(node) {
100	        const tag = tagNameOf(node);
101	        if (tag !== 'SelectTrigger') return;
102	        if (hasJsxAttribute(node, 'data-mia-filter')) return;
103	        if (hasJsxAttribute(node, 'data-mia-skip')) return;
104	        context.report({
105	          node,
106	          message: `<SelectTrigger> sem \`data-mia-filter="..."\`. Adicione pra MIA glass-box poder selecionar opções.`,
107	        });
108	      },
109	    };
110	  },
111	};
112	
113	export default {
114	  rules: {
115	    'require-data-mia-action': requireActionRule,
116	    'require-data-mia-field': requireFieldRule,
117	    'require-data-mia-filter': requireFilterRule,
118	  },
119	};
