/*
 * Animações do Painel TV (/tv) — lista FECHADA do design.md §8.1.
 * Importado apenas por TvDashboard.page.tsx; nada vaza para o design system.
 */

@media (prefers-reduced-motion: no-preference) {
  /* §8.1.5 — pixel-shift anti burn-in: ciclo de 16 min (960s), passos de
     1-2px com interpolação de ~2s (0.2% de 960s ≈ 1,9s) em cada troca. */
  @keyframes tv-pixel-shift {
    0% {
      transform: translate(0, 0);
    }
    24.8% {
      transform: translate(0, 0);
    }
    25% {
      transform: translate(1px, 1px);
    }
    49.8% {
      transform: translate(1px, 1px);
    }
    50% {
      transform: translate(0, 2px);
    }
    74.8% {
      transform: translate(0, 2px);
    }
    75% {
      transform: translate(-1px, 1px);
    }
    99.8% {
      transform: translate(-1px, 1px);
    }
    100% {
      transform: translate(0, 0);
    }
  }

  .tv-pixel-shift {
    animation: tv-pixel-shift 960s ease-in-out infinite;
  }

  /* §8.1.2 — fade-in de exceção nova (uma única vez) */
  @keyframes tv-fade-in {
    from {
      opacity: 0;
      transform: translateY(6px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .tv-fade-in {
    animation: tv-fade-in 300ms ease-out both;
  }

  /* §7 — conteúdo entra com fade único de 300ms após o primeiro load */
  @keyframes tv-content-enter {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  .tv-content-enter {
    animation: tv-content-enter 300ms ease-out both;
  }

  /* §7 — loading inicial: 3 pontos que acendem em sequência (1×/600ms),
     único movimento permitido fora do estado carregado. */
  @keyframes tv-dot {
    0%,
    100% {
      opacity: 0.2;
    }
    33% {
      opacity: 1;
    }
  }

  .tv-dot {
    animation: tv-dot 1800ms steps(3, jump-none) infinite;
  }

  .tv-dot:nth-child(2) {
    animation-delay: 600ms;
  }

  .tv-dot:nth-child(3) {
    animation-delay: 1200ms;
  }
}

/* §8.1.3/§8.1.4 — transições de barra e de estado RAG valem mesmo com
   reduced-motion? Não: §8.1.7 manda trocar seco. As classes utilitárias de
   transição são aplicadas via Tailwind nos componentes; aqui apenas as
   desligamos sob reduced-motion. */
@media (prefers-reduced-motion: reduce) {
  .tv-pixel-shift,
  .tv-fade-in,
  .tv-content-enter,
  .tv-dot {
    animation: none;
  }
}

/**
 * @module features/tv-dashboard/ui/tvFormat
 *
 * Formatadores de APRESENTAÇÃO do Painel TV (camada UI).
 * Regras de negócio/agregação vivem em `../model/tvMath` — aqui só render.
 */

import { businessDayFraction } from '../model/tvMath';

/** Cor semântica da barra de meta (design.md §1.6 — estado de VENDA). */
export type TvBarColor = 'sage' | 'amber' | 'red';

/** Abreviações pt-BR dos dias da semana (índice = `Date.getDay()`). */
export const WEEKDAY_ABBR = [
  'dom.',
  'seg.',
  'ter.',
  'qua.',
  'qui.',
  'sex.',
  'sáb.',
] as const;

/** Hora local `HH:MM` (sem segundos — design.md §1.5), ou null sem dado. */
export function formatTimeHHMM(value: Date | string | null | undefined): string | null {
  if (value == null) return null;
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) return null;
  return d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
}

/** Contagem inteira com separador de milhar pt-BR ("1.240"). */
export function formatInt(value: number): string {
  return Math.round(value).toLocaleString('pt-BR');
}

/** Ticket médio sempre com 2 decimais ("R$ 38,50" — design.md §1.5). */
export function formatTicketBRL(value: number): string {
  return `R$ ${value.toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

/** Delta com sinal e seta textual implícita ("12%" — sinal vem do ícone). */
export function formatDeltaPct(delta: number): string {
  return `${Math.abs(Math.round(delta))}%`;
}

/** Rótulo "ter. 03/06" para o dia de referência de canal defasado. */
export function formatWeekdayDayMonth(date: Date): string {
  const dd = String(date.getDate()).padStart(2, '0');
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  return `${WEEKDAY_ABBR[date.getDay()]} ${dd}/${mm}`;
}

/** "há 12 min" / "há 3h" para timestamps recentes; null sem dado. */
export function formatAgoLabel(
  value: Date | string | null | undefined,
  now: Date,
): string | null {
  if (value == null) return null;
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) return null;
  const diffMin = Math.max(0, Math.floor((now.getTime() - d.getTime()) / 60_000));
  if (diffMin < 60) return `há ${diffMin} min`;
  return `há ${Math.floor(diffMin / 60)}h`;
}

/**
 * Cor da barra de % meta a partir do ratio pró-rata (`%real / %esperado`,
 * em fração: 1.0 = exatamente no ritmo). Regra do design.md §1.6:
 * sage ≥ 0,9 · âmbar 0,75–0,9 · vermelho < 0,6 após 12:00 (0,6–0,75 âmbar).
 * Ratio nulo (sem meta / antes da janela) fica sage — barra neutra.
 */
export function metaBarColorFromRatio(ratio: number | null, now: Date): TvBarColor {
  if (ratio == null) return 'sage';
  if (ratio >= 0.9) return 'sage';
  if (ratio >= 0.75) return 'amber';
  if (ratio < 0.6 && now.getHours() >= 12) return 'red';
  return 'amber';
}

/** % esperado AGORA da meta do dia (posição do tick pró-rata), 0–100. */
export function expectedPctNow(now: Date): number {
  return Math.round(businessDayFraction(now) * 100);
}

/** Limita um percentual de preenchimento de barra ao intervalo [0, 100]. */
export function clampPct(pct: number | null): number {
  if (pct == null || Number.isNaN(pct)) return 0;
  return Math.max(0, Math.min(100, pct));
}

/**
 * @module features/tv-dashboard/ui/useCountUp
 *
 * Count-up de número do Painel TV (design.md §8.1.1): ao mudar de valor,
 * anima 400ms ease-out do valor antigo para o novo. Nunca em loop.
 * `prefers-reduced-motion: reduce` troca o valor seco (§8.1.7).
 */

import { useEffect, useRef, useState } from 'react';

/** Duração padrão do count-up (design.md §8.1.1). */
const COUNT_UP_MS = 400;

function easeOut(t: number): number {
  return 1 - (1 - t) * (1 - t);
}

function prefersReducedMotion(): boolean {
  return (
    typeof window !== 'undefined' &&
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  );
}

/**
 * Interpola `value` ao longo de 400ms quando ele muda (uma única vez por
 * mudança). No primeiro render retorna o valor direto (sem animar de 0).
 */
export function useCountUp(value: number, durationMs: number = COUNT_UP_MS): number {
  const [display, setDisplay] = useState(value);
  const fromRef = useRef(value);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    const from = fromRef.current;
    if (from === value) return;
    if (prefersReducedMotion() || typeof requestAnimationFrame !== 'function') {
      fromRef.current = value;
      setDisplay(value);
      return;
    }
    const start = performance.now();
    const step = (ts: number) => {
      const t = Math.min(1, (ts - start) / durationMs);
      const next = from + (value - from) * easeOut(t);
      setDisplay(next);
      if (t < 1) {
        rafRef.current = requestAnimationFrame(step);
      } else {
        fromRef.current = value;
        rafRef.current = null;
      }
    };
    rafRef.current = requestAnimationFrame(step);
    return () => {
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
      fromRef.current = value;
    };
  }, [value, durationMs]);

  return display;
}

/**
 * @module features/tv-dashboard/ui/useMinuteClock
 *
 * Relógio do Painel TV: atualiza 1×/minuto, alinhado à virada do minuto
 * (design.md §3 zona 4 — sem segundos; segundos = movimento contínuo).
 */

import { useEffect, useState } from 'react';

/** Retorna o instante atual, re-renderizando uma vez por minuto. */
export function useMinuteClock(): Date {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    let timer: number;
    const schedule = () => {
      // +80ms de folga pra garantir que já virou o minuto
      timer = window.setTimeout(() => {
        setNow(new Date());
        schedule();
      }, 60_000 - (Date.now() % 60_000) + 80);
    };
    schedule();
    return () => window.clearTimeout(timer);
  }, []);

  return now;
}

/**
 * @module features/tv-dashboard/ui/TvChips
 *
 * Blocos visuais compartilhados do Painel TV: chip de delta semanal,
 * chip de fonte (ao vivo / atrasado / defasado Linx), chip de estado RAG,
 * badge de estoque e barra de % meta com tick de esperado.
 * Tokens e medidas: design.md §1.3–§1.6, §3 e §4.
 */

import {
  ArrowDown,
  ArrowUp,
  CalendarClock,
  Check,
  OctagonAlert,
  RefreshCw,
  TriangleAlert,
} from 'lucide-react';
import type {
  TvFreshnessLevel,
  TvRagStatus,
  TvSalesChannel,
  TvStockAlertSummary,
} from '../model/types';
import { formatLaggedDateLabel } from '../model/tvMath';
import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';

// ─────────────────────────────────────────────────────────────────────────────
// Delta semanal (vs mesmo dia da semana passada — nunca "ontem")
// ─────────────────────────────────────────────────────────────────────────────

interface TvDeltaChipProps {
  /** Delta % vs mesmo dia da semana anterior. */
  delta: number;
  /** Abreviação do dia comparado ("qua."). */
  weekdayLabel: string;
  /** Tamanho: hero (28px) ou card de loja (24px). */
  size: 'hero' | 'card';
}

/**
 * Chip de delta semanal. Cor `tv-mut` sempre — exceto delta ≤ −15%,
 * que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
 */
export function TvDeltaChip({ delta, weekdayLabel, size }: TvDeltaChipProps) {
  const isAlert = delta <= -15;
  const colorCls = isAlert ? 'text-tv-amber' : 'text-tv-mut';
  const textCls = size === 'hero' ? 'text-[28px]' : 'text-[24px]';
  const iconPx = size === 'hero' ? 28 : 24;
  const Icon = delta < 0 ? ArrowDown : ArrowUp;
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full bg-tv-raised px-4 py-1.5 font-tv-num font-medium tabular-nums leading-none ${textCls} ${colorCls}`}
      data-testid="tv-delta-chip"
    >
      <Icon style={{ width: iconPx, height: iconPx }} aria-hidden />
      {formatDeltaPct(delta)} vs {weekdayLabel}
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip de fonte (freshness honesta — design.md §4 item 1)
// ─────────────────────────────────────────────────────────────────────────────

interface TvSourceChipProps {
  channel: TvSalesChannel;
  /** Freshness da fonte live (ignorado para canal Linx). */
  liveLevel: TvFreshnessLevel;
  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
  laggedDate?: string | null;
}

/**
 * Chip de fonte do card: Degust fresco → "✓ ao vivo"; Degust atrasado →
 * "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM" (defasagem esperada
 * não é alarme).
 */
export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
  if (channel === 'linx-lagged') {
    return (
      <span
        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-mut"
        data-testid="tv-source-chip-lagged"
      >
        <CalendarClock style={{ width: 18, height: 18 }} aria-hidden />
        {laggedDate ? formatLaggedDateLabel(laggedDate) : 'sem dados'}
      </span>
    );
  }
  if (liveLevel === 'fresh') {
    return (
      <span
        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-sageup"
        data-testid="tv-source-chip-live"
      >
        <Check style={{ width: 18, height: 18 }} aria-hidden />
        ao vivo
      </span>
    );
  }
  return (
    <span
      className="inline-flex h-6 items-center gap-1.5 rounded-full border border-tv-amber/40 bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-amber"
      data-testid="tv-source-chip-stale"
    >
      <RefreshCw style={{ width: 18, height: 18 }} aria-hidden />
      atrasado
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip de estado RAG (redundância não-cromática lível a 3m)
// ─────────────────────────────────────────────────────────────────────────────

/** Chip "⚠ ATENÇÃO" / "⛔ CRÍTICO" do header do card. Nulo em estado ok. */
export function TvStateChip({ rag }: { rag: TvRagStatus }) {
  if (rag === 'ok') return null;
  if (rag === 'red') {
    return (
      <span
        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-red/15 px-3 text-[20px] font-momma font-medium leading-none text-tv-redsoft"
        data-testid="tv-state-chip-red"
      >
        <OctagonAlert style={{ width: 18, height: 18 }} aria-hidden />
        CRÍTICO
      </span>
    );
  }
  return (
    <span
      className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-amber/15 px-3 text-[20px] font-momma font-medium leading-none text-tv-amber"
      data-testid="tv-state-chip-amber"
    >
      <TriangleAlert style={{ width: 18, height: 18 }} aria-hidden />
      ATENÇÃO
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Badge de estoque (contagem; vermelho absorve âmbar quando há ambos)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
 */
export function TvStockBadge({ estoque }: { estoque: TvStockAlertSummary }) {
  const total = estoque.zerados + estoque.abaixoMinimo;
  if (total === 0) return null;
  if (estoque.zerados > 0) {
    return (
      <span
        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-red/15 px-3 text-[20px] font-tv-num font-medium leading-none text-tv-redsoft tabular-nums"
        data-testid="tv-stock-badge-red"
      >
        <OctagonAlert style={{ width: 18, height: 18 }} aria-hidden />
        {total}
      </span>
    );
  }
  return (
    <span
      className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-amber/15 px-3 text-[20px] font-tv-num font-medium leading-none text-tv-amber tabular-nums"
      data-testid="tv-stock-badge-amber"
    >
      <TriangleAlert style={{ width: 18, height: 18 }} aria-hidden />
      {total}
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Barra de % meta com tick de "esperado agora"
// ─────────────────────────────────────────────────────────────────────────────

const BAR_FILL_CLS: Record<TvBarColor, string> = {
  sage: 'bg-tv-sage',
  amber: 'bg-tv-amber',
  red: 'bg-tv-red',
};

interface TvMetaBarProps {
  /** % do dia COMPLETO da meta já atingido (preenchimento), ou null. */
  fillPct: number | null;
  /** Posição do tick de "esperado agora" (0–100), ou null para ocultar. */
  expectedPct: number | null;
  /** Cor semântica do preenchimento (estado de venda — design.md §1.6). */
  color: TvBarColor;
  /** Altura da barra: hero 20px, card 12px. */
  size: 'hero' | 'card';
}

/**
 * Barra horizontal de % meta com trilho `tv-track`, preenchimento colorido
 * por estado de venda e tick vertical de "esperado agora" (pró-rata).
 * Transição de width 600ms ease-out (design.md §8.1.3).
 */
export function TvMetaBar({ fillPct, expectedPct, color, size }: TvMetaBarProps) {
  const heightCls = size === 'hero' ? 'h-5' : 'h-3';
  const tick =
    size === 'hero'
      ? { width: 3, height: 28, offset: -4 }
      : { width: 2, height: 20, offset: -4 };
  return (
    <div className={`relative w-full rounded-full bg-tv-track ${heightCls}`} data-testid="tv-meta-bar">
      {fillPct != null && (
        <div
          className={`absolute inset-y-0 left-0 rounded-full transition-[width] duration-[600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
          style={{ width: `${clampPct(fillPct)}%` }}
          data-testid="tv-meta-bar-fill"
        />
      )}
      {expectedPct != null && (
        <div
          className="absolute rounded-full bg-tv-text/60"
          style={{
            left: `calc(${clampPct(expectedPct)}% - ${tick.width / 2}px)`,
            top: tick.offset,
            width: tick.width,
            height: tick.height,
          }}
          data-testid="tv-meta-bar-tick"
        />
      )}
    </div>
  );
}

/**
 * @module features/tv-dashboard/ui/TvHero
 *
 * Hero do Painel TV (1856×152 — design.md §3): vendas da rede hoje +
 * delta vs mesmo dia da semana passada, barra de % meta pró-rata com tick
 * de "esperado agora", contador de alertas críticos e relógio + freshness.
 */

import { Check, OctagonAlert, RefreshCw } from 'lucide-react';
import type { TvFreshness, TvNetworkSummary } from '../model/types';
import { formatCompactBRL } from '../model/tvMath';
import { TvDeltaChip, TvMetaBar } from './TvChips';
import {
  WEEKDAY_ABBR,
  expectedPctNow,
  formatTimeHHMM,
  metaBarColorFromRatio,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvHeroProps {
  network: TvNetworkSummary | null;
  freshness: TvFreshness;
  now: Date;
}

/** Hero da rede: 4 zonas em grid fixo (600/460/360/1fr — design.md §3). */
export function TvHero({ network, freshness, now }: TvHeroProps) {
  const vendas = useCountUp(network?.vendasHoje ?? 0);
  const hasData = network != null;

  // Barra: preenchimento = % do dia COMPLETO da meta; tick = esperado agora.
  const fullDayPct =
    network && network.metaDia != null && network.metaDia > 0
      ? (network.vendasHoje / network.metaDia) * 100
      : null;
  const expected = expectedPctNow(now);
  const ratio = network?.pctMetaProRata != null ? network.pctMetaProRata / 100 : null;
  const barColor = metaBarColorFromRatio(ratio, now);

  const alertas = network?.alertasCriticos ?? 0;
  const alertasAnim = Math.round(useCountUp(alertas));

  const liveFresh = freshness.vendasLive.level === 'fresh';
  const liveTime = formatTimeHHMM(freshness.vendasLive.updatedAt);

  return (
    <header className="grid grid-cols-[600px_460px_360px_1fr] items-end gap-8 border-b border-tv-gold/25 pb-4">
      {/* Zona 1 — vendas da rede */}
      <div>
        <div className="flex items-baseline gap-3">
          <span className="text-[22px] font-momma font-bold uppercase tracking-[0.2em] text-tv-gold">
            MOMMA
          </span>
          <span className="text-[22px] text-tv-mut">·</span>
          <span className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
            REDE HOJE
          </span>
        </div>
        <div className="mt-1 flex items-end gap-4">
          <span
            className="font-tv-num text-[100px] font-bold leading-none text-tv-text tabular-nums"
            data-testid="tv-hero-sales"
          >
            {hasData ? formatCompactBRL(vendas) : '—'}
          </span>
          {network?.deltaSemana != null && (
            <span className="pb-2">
              <TvDeltaChip
                delta={network.deltaSemana}
                weekdayLabel={WEEKDAY_ABBR[now.getDay()]}
                size="hero"
              />
            </span>
          )}
        </div>
      </div>

      {/* Zona 2 — % da meta (pró-rata) */}
      <div>
        <span className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
          % DA META (PRÓ-RATA)
        </span>
        <div className="mt-3 w-[420px]">
          <TvMetaBar
            fillPct={fullDayPct}
            expectedPct={fullDayPct != null ? expected : null}
            color={barColor}
            size="hero"
          />
        </div>
        <div className="mt-2 flex items-baseline gap-4">
          {fullDayPct != null ? (
            <>
              <span className="font-tv-num text-[40px] font-bold leading-none text-tv-text tabular-nums">
                {Math.round(fullDayPct)}%
              </span>
              <span className="text-[22px] font-momma text-tv-dim">
                esperado {expected}%
              </span>
            </>
          ) : (
            <span className="text-[22px] font-momma text-tv-dim">
              sem meta cadastrada
            </span>
          )}
        </div>
      </div>

      {/* Zona 3 — alertas críticos */}
      <div>
        <span className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
          ALERTAS CRÍTICOS
        </span>
        <div className="mt-1 flex items-center gap-3" data-testid="tv-hero-alerts">
          {alertas === 0 ? (
            <>
              <Check style={{ width: 40, height: 40 }} className="text-tv-sageup" aria-hidden />
              <span className="font-tv-num text-[72px] font-bold leading-none text-tv-sageup tabular-nums">
                0
              </span>
            </>
          ) : (
            <>
              <OctagonAlert style={{ width: 48, height: 48 }} className="text-tv-red" aria-hidden />
              <span className="font-tv-num text-[72px] font-bold leading-none text-tv-red tabular-nums">
                {alertasAnim}
              </span>
            </>
          )}
        </div>
      </div>

      {/* Zona 4 — relógio + freshness (à direita) */}
      <div className="flex flex-col items-end gap-2">
        <span className="font-tv-num text-[64px] font-medium leading-none text-tv-text tabular-nums">
          {formatTimeHHMM(now)}
        </span>
        {liveFresh ? (
          <span className="inline-flex items-center gap-2 rounded-full bg-tv-raised px-4 py-1 text-[22px] font-momma font-medium text-tv-sageup">
            <Check style={{ width: 20, height: 20 }} aria-hidden />
            ao vivo{liveTime ? ` · ${liveTime}` : ''}
          </span>
        ) : (
          <span className="inline-flex items-center gap-2 rounded-full border border-tv-amber/40 bg-tv-raised px-4 py-1 text-[22px] font-momma font-medium text-tv-amber">
            <RefreshCw style={{ width: 20, height: 20 }} aria-hidden />
            atrasado{liveTime ? ` · último ${liveTime}` : ''}
          </span>
        )}
      </div>
    </header>
  );
}

/**
 * @module features/tv-dashboard/ui/TvStoreCard
 *
 * Card de loja do Painel TV (602×280 — design.md §4): vendas do dia (ou
 * defasadas com selo honesto), barra de % meta, mini-stats e borda RAG
 * com redundância não-cromática (glow + chip de estado).
 */

import { ArrowDownRight, ArrowUpRight } from 'lucide-react';
import type { TvFreshnessLevel, TvStoreData } from '../model/types';
import { formatCompactBRL, parseIsoDateLocal } from '../model/tvMath';
import {
  TvDeltaChip,
  TvMetaBar,
  TvSourceChip,
  TvStateChip,
  TvStockBadge,
} from './TvChips';
import {
  WEEKDAY_ABBR,
  expectedPctNow,
  formatInt,
  formatTicketBRL,
  formatTimeHHMM,
  formatWeekdayDayMonth,
  metaBarColorFromRatio,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvStoreCardProps {
  store: TvStoreData;
  /** Freshness consolidado da fonte de vendas live (chip "ao vivo"/"atrasado"). */
  liveLevel: TvFreshnessLevel;
  now: Date;
}

/** Borda + glow por estado RAG (design.md §4 — sinal lível a 5m). */
const RAG_FRAME: Record<TvStoreData['rag'], { cls: string; shadow?: string }> = {
  ok: { cls: 'border border-tv-border' },
  amber: {
    cls: 'border-2 border-tv-amber',
    shadow: '0 0 0 1px #F5A623, 0 0 28px -8px rgba(245,166,35,0.45)',
  },
  red: {
    cls: 'border-2 border-tv-red',
    shadow: '0 0 0 1px #E5484D, 0 0 32px -8px rgba(229,72,77,0.55)',
  },
};

/** Card de loja: cobre canal Degust live e Linx defasado. */
export function TvStoreCard({ store, liveLevel, now }: TvStoreCardProps) {
  const { vendas, metaDia, channel } = store;
  const isLive = channel === 'degust-live';
  const valorAnim = useCountUp(vendas?.valor ?? 0);
  const cuponsAnim = Math.round(useCountUp(vendas?.cupons ?? 0));
  const frame = RAG_FRAME[store.rag];

  // Barra: preenchimento = % do dia COMPLETO; tick pró-rata só no canal live
  const fullDayPct =
    vendas != null && metaDia != null && metaDia > 0
      ? (vendas.valor / metaDia) * 100
      : null;
  const expected = isLive ? expectedPctNow(now) : null;
  const barColor = isLive
    ? metaBarColorFromRatio(store.pctMeta != null ? store.pctMeta / 100 : null, now)
    : 'sage';

  const bipTime = formatTimeHHMM(store.movimentacao.ultimaBipagem);
  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;

  // Caption sob as vendas (design.md §4 item 4)
  let caption: string;
  if (vendas == null) {
    caption = 'sem dado de venda disponível';
  } else if (isLive) {
    const upd = formatTimeHHMM(vendas.atualizadoEm);
    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}${bipTime ? ` · bip ${bipTime}` : ''}`;
  } else {
    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados${bipTime ? ` · bip ${bipTime}` : ''}`;
  }

  return (
    <section
      className={`flex flex-col rounded-2xl bg-tv-surface p-5 transition-[border-color,box-shadow] duration-[400ms] motion-reduce:transition-none ${frame.cls}`}
      style={frame.shadow ? { boxShadow: frame.shadow } : undefined}
      data-testid="tv-store-card"
      data-rag={store.rag}
    >
      {/* Header: nome + chips */}
      <div className="flex h-8 items-center justify-between gap-3">
        <h2 className="truncate text-[28px] font-momma font-semibold leading-8 text-tv-text">
          {store.nome}
        </h2>
        <div className="flex shrink-0 items-center gap-2">
          <TvStateChip rag={store.rag} />
          <TvStockBadge estoque={store.estoque} />
          <TvSourceChip
            channel={channel}
            liveLevel={liveLevel}
            laggedDate={vendas?.dataReferencia ?? null}
          />
        </div>
      </div>

      {/* Vendas (64px) + delta */}
      <div className="mt-1.5 flex items-end gap-4">
        <span
          className={`font-tv-num text-[64px] font-bold leading-none tabular-nums ${vendas ? 'text-tv-text' : 'text-tv-dim'}`}
          data-testid="tv-store-sales"
        >
          {vendas ? formatCompactBRL(valorAnim) : '—'}
        </span>
        {store.deltaSemana != null && refDate != null && (
          <span className="pb-1">
            <TvDeltaChip
              delta={store.deltaSemana}
              weekdayLabel={WEEKDAY_ABBR[refDate.getDay()]}
              size="card"
            />
          </span>
        )}
      </div>
      <p className="mt-1 text-[20px] font-momma font-medium leading-tight text-tv-dim">
        {caption}
      </p>

      {/* Barra de meta */}
      <div className="mt-2">
        <TvMetaBar
          fillPct={fullDayPct}
          expectedPct={fullDayPct != null ? expected : null}
          color={barColor}
          size="card"
        />
        <p className="mt-1.5 text-[22px] font-momma leading-tight">
          {fullDayPct != null ? (
            isLive ? (
              <>
                <span className="font-medium text-tv-mut">
                  {Math.round(fullDayPct)}% da meta
                </span>
                <span className="text-tv-dim"> · esperado {expected}%</span>
              </>
            ) : (
              <span className="font-medium text-tv-mut">
                {Math.round(fullDayPct)}% da meta de{' '}
                {refDate ? WEEKDAY_ABBR[refDate.getDay()] : '—'}
              </span>
            )
          ) : (
            <span className="text-tv-dim">sem meta cadastrada</span>
          )}
        </p>
      </div>

      {/* Mini-stats */}
      <div className="mt-auto grid grid-cols-3 gap-4">
        <div>
          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
            CUPONS
          </p>
          <p className="mt-0.5 font-tv-num text-[32px] font-medium leading-none text-tv-text tabular-nums">
            {vendas?.cupons != null ? formatInt(cuponsAnim) : '—'}
          </p>
        </div>
        <div>
          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
            TICKET
          </p>
          <p className="mt-0.5 font-tv-num text-[32px] font-medium leading-none text-tv-text tabular-nums">
            {vendas?.ticketMedio != null ? formatTicketBRL(vendas.ticketMedio) : '—'}
          </p>
        </div>
        <div>
          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
            FLUXO
          </p>
          <p className="mt-0.5 flex items-center gap-1 font-tv-num text-[28px] font-medium leading-none text-tv-text tabular-nums">
            <ArrowUpRight style={{ width: 22, height: 22 }} className="text-tv-mut" aria-hidden />
            {store.movimentacao.entradas}
            <ArrowDownRight
              style={{ width: 22, height: 22 }}
              className="ml-2 text-tv-mut"
              aria-hidden
            />
            {store.movimentacao.saidas}
          </p>
        </div>
      </div>
    </section>
  );
}

/**
 * @module features/tv-dashboard/ui/TvFabricaCard
 *
 * Card diferenciado da fábrica (602×280, posição 6 — design.md §5):
 * produção do dia (com data de referência explícita quando fallback),
 * expedições, última bipagem e hairline gold de identidade.
 */

import { Factory } from 'lucide-react';
import type { TvFactoryData, TvFreshness } from '../model/types';
import { parseIsoDateLocal, toIsoDateLocal } from '../model/tvMath';
import { TvSourceChip, TvStateChip, TvStockBadge } from './TvChips';
import {
  formatAgoLabel,
  formatInt,
  formatTimeHHMM,
  formatWeekdayDayMonth,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvFabricaCardProps {
  factory: TvFactoryData;
  freshness: TvFreshness;
  now: Date;
}

/** Janela de produção da fábrica para o alerta visual de bipagem (§5). */
const FACTORY_HOURS = { start: 6, end: 18 } as const;

/** Borda + glow por estado RAG (mesmo chassi do TvStoreCard). */
const RAG_FRAME: Record<TvFactoryData['rag'], { cls: string; shadow?: string }> = {
  ok: { cls: 'border border-tv-border' },
  amber: {
    cls: 'border-2 border-tv-amber',
    shadow: '0 0 0 1px #F5A623, 0 0 28px -8px rgba(245,166,35,0.45)',
  },
  red: {
    cls: 'border-2 border-tv-red',
    shadow: '0 0 0 1px #E5484D, 0 0 32px -8px rgba(229,72,77,0.55)',
  },
};

/** Card da fábrica: nunca tem meta de venda — só produção/expedição/bip. */
export function TvFabricaCard({ factory, freshness, now }: TvFabricaCardProps) {
  const producao = factory.producao;
  const unidadesAnim = Math.round(useCountUp(producao?.totalUnidades ?? 0));
  const frame = RAG_FRAME[factory.rag];

  const todayIso = toIsoDateLocal(now);
  const isToday = producao?.dataReferencia === todayIso;
  const refLabel =
    producao && !isToday
      ? formatWeekdayDayMonth(parseIsoDateLocal(producao.dataReferencia))
      : null;
  const updTime = formatTimeHHMM(freshness.estoque.updatedAt);

  // Última bipagem: âmbar quando >2h dentro da janela de produção (06–18h)
  const bip = factory.expedicoes.ultimaBipagem;
  const bipTime = formatTimeHHMM(bip);
  const bipAgo = formatAgoLabel(bip, now);
  const hour = now.getHours();
  const inProductionWindow = hour >= FACTORY_HOURS.start && hour < FACTORY_HOURS.end;
  const bipStale =
    inProductionWindow &&
    (bip == null || now.getTime() - new Date(bip).getTime() > 2 * 3_600_000);
  const bipColor = bipStale ? 'text-tv-amber' : 'text-tv-text';

  return (
    <section
      className={`relative flex flex-col overflow-hidden rounded-2xl bg-tv-surface p-5 transition-[border-color,box-shadow] duration-[400ms] motion-reduce:transition-none ${frame.cls}`}
      style={frame.shadow ? { boxShadow: frame.shadow } : undefined}
      data-testid="tv-fabrica-card"
      data-rag={factory.rag}
    >
      {/* Hairline gold de identidade (topo, sob o radius) */}
      <div className="absolute inset-x-0 top-0 h-0.5 bg-tv-gold/50" aria-hidden />

      {/* Header */}
      <div className="flex h-8 items-center justify-between gap-3">
        <h2 className="flex items-center gap-2.5 truncate text-[28px] font-momma font-semibold leading-8 text-tv-text">
          <Factory style={{ width: 26, height: 26 }} className="shrink-0 text-tv-gold" aria-hidden />
          {factory.nome}
        </h2>
        <div className="flex shrink-0 items-center gap-2">
          <TvStateChip rag={factory.rag} />
          <TvStockBadge estoque={factory.estoque} />
          <TvSourceChip channel="factory" liveLevel={freshness.estoque.level} />
        </div>
      </div>

      {/* Produção (64px) */}
      <div className="mt-1.5 flex items-end gap-3">
        <span
          className={`font-tv-num text-[64px] font-bold leading-none tabular-nums ${producao ? 'text-tv-text' : 'text-tv-dim'}`}
          data-testid="tv-fabrica-producao"
        >
          {producao ? formatInt(unidadesAnim) : '—'}
        </span>
        {producao && (
          <span className="pb-0.5 font-tv-num text-[32px] font-normal leading-none text-tv-mut">
            un
          </span>
        )}
      </div>
      <p className="mt-1 text-[20px] font-momma font-medium leading-tight text-tv-dim">
        {producao
          ? `produzido ${refLabel ? `em ${refLabel}` : 'hoje'}${updTime ? ` · atualizado ${updTime}` : ''}`
          : 'sem produção registrada'}
      </p>

      {/* Respiro extra intencional — fábrica não tem barra de meta (§5) */}
      <div className="mt-auto grid grid-cols-3 gap-4">
        <div>
          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
            EXPEDIÇÕES
          </p>
          <p className="mt-0.5 font-tv-num text-[32px] font-medium leading-none text-tv-text tabular-nums">
            {formatInt(factory.expedicoes.saidas)}
          </p>
        </div>
        <div>
          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
            ITENS PROD.
          </p>
          <p className="mt-0.5 font-tv-num text-[32px] font-medium leading-none text-tv-text tabular-nums">
            {producao ? formatInt(producao.itens) : '—'}
          </p>
        </div>
        <div>
          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
            ÚLT. BIPAGEM
          </p>
          <p
            className={`mt-0.5 font-tv-num text-[32px] font-medium leading-none tabular-nums ${bipColor}`}
            data-testid="tv-fabrica-bip"
          >
            {bipTime ?? '—'}
          </p>
          {bipAgo && (
            <p className={`mt-0.5 text-[20px] font-momma leading-tight ${bipStale ? 'text-tv-amber' : 'text-tv-dim'}`}>
              {bipAgo}
            </p>
          )}
        </div>
      </div>
    </section>
  );
}

/**
 * @module features/tv-dashboard/ui/TvExceptions
 *
 * Faixa de exceções do Painel TV (1229×248 — design.md §6.1): grid 2×4
 * preenchido coluna-primeiro, máx 7 itens + slot de overflow "+N outros",
 * cor SOMENTE na severidade e estado vazio explícito (nunca área em branco).
 */

import { CheckCircle2, OctagonAlert, TriangleAlert } from 'lucide-react';
import type { TvException, TvExceptionsResult } from '../model/types';

/**
 * Separa a linha em texto principal + valor à direita, por tipo de exceção
 * (design.md §6.1 — anatomia da linha).
 */
function splitException(ex: TvException): { text: string; value: string } {
  switch (ex.kind) {
    case 'stock-out':
      return {
        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
        value: '0 un',
      };
    case 'stock-low':
      return {
        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
        value: `${ex.quantidade ?? 0} · mín ${ex.quantidadeMinima ?? 0}`,
      };
    case 'no-movement': {
      const m = ex.message.match(/há \d+\s?h/);
      return {
        text: `${ex.lojaNome ?? 'Loja'} — sem bipagem`,
        value: m ? m[0] : '',
      };
    }
    case 'stale-data': {
      const m = ex.message.match(/desde \d{2}:\d{2}/);
      return {
        text: `${ex.lojaNome ?? 'Venda live'} — dado atrasado`,
        value: m ? m[0] : '',
      };
    }
  }
}

/** Lista de exceções com estado vazio confirmado explicitamente. */
export function TvExceptions({ exceptions }: { exceptions: TvExceptionsResult }) {
  const { items, overflowCount, totalCount } = exceptions;
  const isEmpty = totalCount === 0;

  return (
    <section
      className="flex h-full flex-col rounded-2xl border border-tv-border bg-tv-surface p-5"
      data-testid="tv-exceptions"
    >
      <div className="flex h-7 items-center justify-between">
        <h2 className="text-[24px] font-momma font-semibold uppercase tracking-[0.1em] text-tv-mut">
          EXCEÇÕES
        </h2>
        {totalCount > 0 && (
          <span className="font-tv-num text-[24px] font-medium leading-none text-tv-dim tabular-nums">
            {totalCount}
          </span>
        )}
      </div>

      {isEmpty ? (
        <div
          className="flex h-full items-center justify-center gap-4"
          data-testid="tv-exceptions-empty"
        >
          <CheckCircle2 style={{ width: 44, height: 44 }} className="text-tv-sageup" aria-hidden />
          <p className="text-[28px] font-momma font-medium text-tv-mut">
            Nenhum alerta — tudo dentro do normal
          </p>
        </div>
      ) : (
        <ul className="mt-3 grid flex-1 grid-flow-col grid-cols-2 grid-rows-4 gap-x-6 gap-y-2">
          {items.map((ex) => {
            const { text, value } = splitException(ex);
            const isRed = ex.severity === 'red';
            return (
              <li
                key={ex.id}
                className={`tv-fade-in flex items-center gap-3 rounded-lg px-3 ${
                  isRed ? 'bg-tv-red/[0.08]' : 'bg-tv-amber/[0.06]'
                }`}
                data-testid="tv-exception-row"
                data-severity={ex.severity}
              >
                {isRed ? (
                  <OctagonAlert
                    style={{ width: 24, height: 24 }}
                    className="shrink-0 text-tv-red"
                    aria-hidden
                  />
                ) : (
                  <TriangleAlert
                    style={{ width: 24, height: 24 }}
                    className="shrink-0 text-tv-amber"
                    aria-hidden
                  />
                )}
                <span className="min-w-0 flex-1 truncate text-[24px] font-momma font-medium text-tv-text">
                  {text}
                </span>
                {value && (
                  <span
                    className={`shrink-0 font-tv-num text-[24px] font-medium tabular-nums ${
                      isRed ? 'text-tv-redsoft' : 'text-tv-amber'
                    }`}
                  >
                    {value}
                  </span>
                )}
              </li>
            );
          })}
          {overflowCount > 0 && (
            <li
              className="flex items-center rounded-lg px-3 text-[22px] font-momma text-tv-mut"
              data-testid="tv-exceptions-overflow"
            >
              + {overflowCount} outros alertas
            </li>
          )}
        </ul>
      )}
    </section>
  );
}

/**
 * @module features/tv-dashboard/ui/TvTopProducts
 *
 * Top 5 produtos do dia da rede (603×248 — design.md §6.2): barras
 * horizontais sage MONOCROMÁTICAS (rank = comprimento + ordem, não cor),
 * largura proporcional ao 1º colocado.
 */

import type { TvTopProduct } from '../model/tvMath';
import { formatInt } from './tvFormat';

/** Coluna direita da faixa inferior: top 5 produtos por unidades vendidas. */
export function TvTopProducts({ products }: { products: TvTopProduct[] }) {
  const max = products.length > 0 ? Math.max(...products.map((p) => p.quantidade)) : 0;

  return (
    <section
      className="flex h-full flex-col rounded-2xl border border-tv-border bg-tv-surface p-5"
      data-testid="tv-top-products"
    >
      <h2 className="h-7 text-[22px] font-momma font-semibold uppercase tracking-[0.1em] text-tv-mut">
        TOP 5 PRODUTOS · HOJE
      </h2>

      {products.length === 0 ? (
        <div className="flex h-full flex-col items-center justify-center gap-2">
          <span className="font-tv-num text-[32px] font-medium text-tv-dim">—</span>
          <p className="text-[22px] font-momma text-tv-dim">aguardando vendas do dia</p>
        </div>
      ) : (
        <ul className="mt-2 flex flex-1 flex-col justify-between">
          {products.slice(0, 5).map((p) => (
            <li key={p.nome} className="h-[34px]">
              <div className="flex h-6 items-center justify-between gap-4">
                <span className="min-w-0 flex-1 truncate text-[22px] font-momma font-medium text-tv-mut">
                  {p.nome}
                </span>
                <span className="shrink-0 font-tv-num text-[24px] font-medium leading-none text-tv-text tabular-nums">
                  {formatInt(p.quantidade)}
                </span>
              </div>
              <div
                className="mt-0.5 h-2 rounded-full bg-tv-sage transition-[width] duration-[600ms] ease-out motion-reduce:transition-none"
                style={{ width: `${max > 0 ? Math.max(2, (p.quantidade / max) * 100) : 0}%` }}
                data-testid="tv-top-product-bar"
              />
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

/**
 * @module features/tv-dashboard/ui/TvDashboard.page
 *
 * Página `/tv` — Dashboard de Crise em TV 1920×1080 (design.md §1–§2, §7–§8).
 * Renderiza FORA do DashboardLayout (fullscreen, sem sidebar), dark
 * hardcoded via tokens `tv.*` (independe do toggle de tema), zero scroll.
 */

import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Settings2 } from 'lucide-react';
import { useTvDashboardData } from '../model/useTvDashboardData';
import { useTvRealtime } from '../model/useTvRealtime';
import { TvHero } from './TvHero';
import { TvStoreCard } from './TvStoreCard';
import { TvFabricaCard } from './TvFabricaCard';
import { TvExceptions } from './TvExceptions';
import { TvTopProducts } from './TvTopProducts';
import { useMinuteClock } from './useMinuteClock';
import './tv.css';

/** Tempo que o botão Metas permanece visível após mousemove (§8.4). */
const METAS_BUTTON_VISIBLE_MS = 5_000;

/** Card-chassi anônimo do estado de erro total (design.md §7). */
function TvErrorCard() {
  return (
    <section className="flex flex-col rounded-2xl border border-tv-border bg-tv-surface p-5">
      <div className="flex h-8 items-center justify-between">
        <span className="text-[28px] font-momma font-semibold text-tv-dim">—</span>
        <span className="inline-flex h-6 items-center rounded-full border border-tv-amber/40 bg-tv-raised px-3 text-[20px] font-momma font-medium text-tv-amber">
          sem conexão
        </span>
      </div>
      <span className="mt-4 font-tv-num text-[64px] font-bold leading-none text-tv-dim">—</span>
    </section>
  );
}

/** Página raiz do painel TV. */
export default function TvDashboardPage() {
  const navigate = useNavigate();
  const data = useTvDashboardData();
  useTvRealtime();
  const now = useMinuteClock();

  // Botão fantasma "Metas": invisível por padrão; mousemove revela por 5s
  // e suspende o cursor-none enquanto visível (design.md §8.4).
  const [controlsVisible, setControlsVisible] = useState(false);
  const hideTimer = useRef<number | null>(null);
  useEffect(() => {
    const onMove = () => {
      setControlsVisible(true);
      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
      hideTimer.current = window.setTimeout(
        () => setControlsVisible(false),
        METAS_BUTTON_VISIBLE_MS,
      );
    };
    window.addEventListener('mousemove', onMove);
    return () => {
      window.removeEventListener('mousemove', onMove);
      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
    };
  }, []);

  // ── Loading inicial (§7): wordmark + frase + 3 pontos em sequência ──
  if (data.isLoading) {
    return (
      <div className="fixed inset-0 flex select-none flex-col items-center justify-center gap-5 overflow-hidden bg-tv-bg font-momma antialiased">
        <span className="text-[40px] font-bold uppercase tracking-[0.3em] text-tv-gold">
          MOMMA
        </span>
        <span className="text-[24px] text-tv-mut">carregando painel…</span>
        <div className="flex gap-2 text-[24px] text-tv-dim" aria-hidden>
          <span className="tv-dot">·</span>
          <span className="tv-dot">·</span>
          <span className="tv-dot">·</span>
        </div>
      </div>
    );
  }

  const storeCards = data.stores.slice(0, data.factory ? 5 : 6);

  return (
    <div
      className={`fixed inset-0 select-none overflow-hidden bg-tv-bg font-momma text-tv-text antialiased ${
        controlsVisible ? '' : 'cursor-none'
      }`}
      data-testid="tv-dashboard"
    >
      <div className="tv-pixel-shift h-full">
        <div className="tv-content-enter grid h-full grid-rows-[152px_1fr_248px] gap-6 px-8 py-6">
          {/* Linha 1 — hero */}
          <TvHero network={data.network} freshness={data.freshness} now={now} />

          {/* Linha 2 — grid 3×2 de unidades (fábrica na posição 6) */}
          <div className="grid grid-cols-3 grid-rows-2 gap-6">
            {data.isError ? (
              <>
                {Array.from({ length: 6 }, (_, i) => (
                  <TvErrorCard key={i} />
                ))}
              </>
            ) : (
              <>
                {storeCards.map((store) => (
                  <TvStoreCard
                    key={store.lojaId}
                    store={store}
                    liveLevel={data.freshness.vendasLive.level}
                    now={now}
                  />
                ))}
                {data.factory && (
                  <TvFabricaCard
                    factory={data.factory}
                    freshness={data.freshness}
                    now={now}
                  />
                )}
              </>
            )}
          </div>

          {/* Linha 3 — exceções (2fr) + top 5 produtos (1fr) */}
          <div className="grid grid-cols-[2fr_1fr] gap-6">
            <TvExceptions exceptions={data.exceptions} />
            <TvTopProducts products={data.topProducts} />
          </div>
        </div>
      </div>

      {/* Botão fantasma de Metas (§8.4) */}
      <button
        type="button"
        onClick={() => navigate('/tv/metas')}
        data-mia-action="abrir-metas-painel-tv"
        className={`fixed bottom-6 right-8 flex h-11 items-center gap-2 rounded-full border border-tv-border bg-tv-raised/80 px-5 text-[20px] font-momma font-medium text-tv-dim transition-opacity duration-200 motion-reduce:transition-none ${
          controlsVisible ? 'opacity-100' : 'pointer-events-none opacity-0'
        }`}
        aria-hidden={!controlsVisible}
        tabIndex={controlsVisible ? 0 : -1}
      >
        <Settings2 style={{ width: 22, height: 22 }} aria-hidden />
        Metas
      </button>
    </div>
  );
}

/**
 * @module features/tv-dashboard/ui/TvMetas.page
 *
 * Página `/tv/metas` (admin): grade lojas × dias da semana (dom–sáb) para
 * cadastrar a meta diária de vendas em R$ (`metas_vendas`, upsert por
 * loja_id+dia_semana). Usa o layout normal do app — o DashboardLayout é
 * aplicado na rota (App.tsx), como nas demais páginas.
 */

import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { ArrowLeft, MonitorPlay, Save } from 'lucide-react';
import { toast } from 'sonner';
import { supabase } from '@/integrations/supabase/client';
import { Button } from '@/shared/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/shared/ui/card';
import { Input } from '@/shared/ui/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/shared/ui/table';
import { tvDashboardKeys } from '../model/useTvDashboardData';

/** Cabeçalhos das colunas (índice = `Date.getDay()`: 0=domingo). */
const WEEKDAYS = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'] as const;

interface MetasLoja {
  id: number;
  nome: string;
}

interface MetaRow {
  loja_id: number;
  dia_semana: number;
  valor_meta: number;
}

function cellKey(lojaId: number, dia: number): string {
  return `${lojaId}:${dia}`;
}

function isFactoryTipo(tipo: string | null): boolean {
  const t = (tipo ?? '').toLowerCase();
  return t.startsWith('fabrica') || t.startsWith('fábrica');
}

async function fetchLojasVenda(): Promise<MetasLoja[]> {
  const { data, error } = await supabase
    .from('lojas')
    .select('id, nome, tipo')
    .eq('ativo', true)
    .order('id');
  if (error) throw error;
  return (data ?? [])
    .filter((l) => !isFactoryTipo(l.tipo))
    .map((l) => ({ id: l.id, nome: l.nome }));
}

async function fetchMetas(): Promise<MetaRow[]> {
  const { data, error } = await supabase
    .from('metas_vendas')
    .select('loja_id, dia_semana, valor_meta')
    .limit(1000);
  if (error) throw error;
  return data ?? [];
}

/** Grade de metas do Painel TV (admin only — rota protegida em App.tsx). */
export default function TvMetasPage() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const lojasQuery = useQuery({ queryKey: ['tv-metas', 'lojas'], queryFn: fetchLojasVenda });
  const metasQuery = useQuery({ queryKey: ['tv-metas', 'valores'], queryFn: fetchMetas });

  // Valores dos inputs (string p/ digitação livre), keyed `lojaId:dia`
  const [values, setValues] = useState<Record<string, string>>({});
  const initialized = useRef(false);
  useEffect(() => {
    if (initialized.current || !metasQuery.data) return;
    initialized.current = true;
    const next: Record<string, string> = {};
    for (const meta of metasQuery.data) {
      next[cellKey(meta.loja_id, meta.dia_semana)] =
        meta.valor_meta > 0 ? String(meta.valor_meta) : '';
    }
    setValues(next);
  }, [metasQuery.data]);

  const saveMutation = useMutation({
    mutationFn: async (rows: MetaRow[]) => {
      const { error } = await supabase
        .from('metas_vendas')
        .upsert(rows, { onConflict: 'loja_id,dia_semana' });
      if (error) throw error;
    },
    onSuccess: () => {
      toast.success('Metas salvas com sucesso');
      queryClient.invalidateQueries({ queryKey: ['tv-metas', 'valores'] });
      queryClient.invalidateQueries({ queryKey: tvDashboardKeys.metas() });
    },
    onError: (error: Error) => {
      toast.error('Erro ao salvar metas', {
        description: error.message || 'Tente novamente em instantes.',
      });
    },
  });

  const rows = useMemo(() => {
    const out: MetaRow[] = [];
    for (const loja of lojasQuery.data ?? []) {
      for (let dia = 0; dia <= 6; dia++) {
        const raw = values[cellKey(loja.id, dia)];
        if (raw == null || raw.trim() === '') continue;
        const parsed = Number(raw.replace(',', '.'));
        if (!Number.isFinite(parsed) || parsed < 0) continue;
        out.push({ loja_id: loja.id, dia_semana: dia, valor_meta: parsed });
      }
    }
    return out;
  }, [lojasQuery.data, values]);

  const isLoading = lojasQuery.isLoading || metasQuery.isLoading;

  return (
    <div className="space-y-6 p-4 md:p-6" data-testid="tv-metas-page">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <Button
            variant="outline"
            size="icon"
            onClick={() => navigate('/tv')}
            data-mia-action="voltar-painel-tv"
            aria-label="Voltar para o Painel TV"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="flex items-center gap-2 text-2xl font-bold">
              <MonitorPlay className="h-6 w-6" />
              Metas do Painel TV
            </h1>
            <p className="text-sm text-muted-foreground">
              Meta diária de vendas (R$) por loja e dia da semana — usada no % pró-rata do painel.
            </p>
          </div>
        </div>
        <Button
          onClick={() => saveMutation.mutate(rows)}
          disabled={saveMutation.isPending || isLoading || rows.length === 0}
          data-mia-action="salvar-metas-painel-tv"
        >
          <Save className="mr-2 h-4 w-4" />
          {saveMutation.isPending ? 'Salvando…' : 'Salvar metas'}
        </Button>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Grade de metas</CardTitle>
          <CardDescription>
            Deixe em branco os dias sem meta — o painel mostra "sem meta cadastrada".
          </CardDescription>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <p className="py-8 text-center text-sm text-muted-foreground">
              Carregando metas…
            </p>
          ) : (lojasQuery.data ?? []).length === 0 ? (
            <p className="py-8 text-center text-sm text-muted-foreground">
              Nenhuma loja ativa encontrada.
            </p>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="min-w-[160px]">Loja</TableHead>
                    {WEEKDAYS.map((dia) => (
                      <TableHead key={dia} className="min-w-[110px] text-center">
                        {dia}
                      </TableHead>
                    ))}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {(lojasQuery.data ?? []).map((loja) => (
                    <TableRow key={loja.id} data-testid="tv-metas-row">
                      <TableCell className="font-medium">{loja.nome}</TableCell>
                      {WEEKDAYS.map((_, dia) => {
                        const key = cellKey(loja.id, dia);
                        return (
                          <TableCell key={key} className="text-center">
                            <Input
                              type="number"
                              min={0}
                              step={50}
                              inputMode="decimal"
                              placeholder="R$"
                              className="mx-auto w-24 text-right"
                              value={values[key] ?? ''}
                              onChange={(e) =>
                                setValues((prev) => ({ ...prev, [key]: e.target.value }))
                              }
                              data-mia-field={`meta-${loja.id}-dia-${dia}`}
                              aria-label={`Meta de ${loja.nome} — ${WEEKDAYS[dia]}`}
                            />
                          </TableCell>
                        );
                      })}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

