import { render, screen } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import { TvStoreCard } from './TvStoreCard';
import type { TvStoreData } from '../model/types';

// qui 04/06/2026, 14:30 — dentro da janela comercial
const NOW = new Date(2026, 5, 4, 14, 30);

const baseStore: TvStoreData = {
  lojaId: 5,
  nome: 'Momma Águas Claras',
  channel: 'degust-live',
  vendas: {
    valor: 8400,
    cupons: 184,
    ticketMedio: 38.5,
    dataReferencia: '2026-06-04',
    isLive: true,
    caixaAberto: true,
    atualizadoEm: new Date(2026, 5, 4, 14, 28).toISOString(),
  },
  metaDia: 10_000,
  pctMeta: 120,
  deltaSemana: 6,
  estoque: { zerados: 0, abaixoMinimo: 0 },
  movimentacao: {
    entradas: 12,
    saidas: 8,
    ultimaBipagem: new Date(2026, 5, 4, 14, 21).toISOString(),
  },
  rag: 'ok',
  ragReasons: [],
};

describe('TvStoreCard — estados RAG', () => {
  it('NEUTRO: sem chip de estado, com chip "ao vivo"', () => {
    render(<TvStoreCard store={baseStore} liveLevel="fresh" now={NOW} />);
    const card = screen.getByTestId('tv-store-card');
    expect(card).toHaveAttribute('data-rag', 'ok');
    expect(screen.queryByText('ATENÇÃO')).not.toBeInTheDocument();
    expect(screen.queryByText('CRÍTICO')).not.toBeInTheDocument();
    expect(screen.getByTestId('tv-source-chip-live')).toBeInTheDocument();
    expect(screen.getByText('R$ 8,4k')).toBeInTheDocument();
  });

  it('ÂMBAR: chip ATENÇÃO + badge de estoque com contagem', () => {
    const store: TvStoreData = {
      ...baseStore,
      rag: 'amber',
      ragReasons: ['3 itens abaixo do mínimo'],
      estoque: { zerados: 0, abaixoMinimo: 3 },
    };
    render(<TvStoreCard store={store} liveLevel="fresh" now={NOW} />);
    expect(screen.getByTestId('tv-store-card')).toHaveAttribute('data-rag', 'amber');
    expect(screen.getByText('ATENÇÃO')).toBeInTheDocument();
    expect(screen.getByTestId('tv-stock-badge-amber')).toHaveTextContent('3');
  });

  it('VERMELHO: chip CRÍTICO + badge vermelho com a SOMA dos alertas', () => {
    const store: TvStoreData = {
      ...baseStore,
      rag: 'red',
      ragReasons: ['2 itens zerados em alerta'],
      estoque: { zerados: 2, abaixoMinimo: 1 },
    };
    render(<TvStoreCard store={store} liveLevel="fresh" now={NOW} />);
    expect(screen.getByTestId('tv-store-card')).toHaveAttribute('data-rag', 'red');
    expect(screen.getByText('CRÍTICO')).toBeInTheDocument();
    // zerados + abaixoMinimo = 3 (vermelho absorve âmbar)
    expect(screen.getByTestId('tv-stock-badge-red')).toHaveTextContent('3');
    expect(screen.queryByTestId('tv-stock-badge-amber')).not.toBeInTheDocument();
  });
});

describe('TvStoreCard — canal Linx defasado', () => {
  it('exibe selo neutro "até DD/MM" e caption do dia — nunca "ao vivo"', () => {
    const store: TvStoreData = {
      ...baseStore,
      nome: 'Momma Asa Sul',
      channel: 'linx-lagged',
      vendas: {
        valor: 4200,
        cupons: null,
        ticketMedio: null,
        dataReferencia: '2026-06-03', // qua 03/06
        isLive: false,
        caixaAberto: null,
        atualizadoEm: null,
      },
      metaDia: 5000,
      pctMeta: 84,
    };
    render(<TvStoreCard store={store} liveLevel="fresh" now={NOW} />);
    expect(screen.getByTestId('tv-source-chip-lagged')).toHaveTextContent('até 03/06');
    expect(screen.queryByText('ao vivo')).not.toBeInTheDocument();
    expect(screen.getByText(/último dia com dados/)).toBeInTheDocument();
    // Barra do dia completo, % da meta do dia da semana de referência
    expect(screen.getByText(/84% da meta de qua\./)).toBeInTheDocument();
  });
});

describe('TvStoreCard — sem meta cadastrada', () => {
  it('mostra estado honesto no lugar do % da meta', () => {
    const store: TvStoreData = {
      ...baseStore,
      metaDia: null,
      pctMeta: null,
    };
    render(<TvStoreCard store={store} liveLevel="fresh" now={NOW} />);
    expect(screen.getByText('sem meta cadastrada')).toBeInTheDocument();
    expect(screen.queryByText(/% da meta/)).not.toBeInTheDocument();
  });
});

import { render, screen } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import { TvExceptions } from './TvExceptions';
import type { TvException, TvExceptionsResult } from '../model/types';

function stockOut(i: number): TvException {
  return {
    id: `stock-out:4:Produto ${i}`,
    kind: 'stock-out',
    severity: 'red',
    lojaId: 4,
    lojaNome: 'Momma Lago Sul',
    message: `Produto ${i} zerado — Momma Lago Sul`,
    produtoNome: `Produto ${i}`,
    quantidade: 0,
    quantidadeMinima: 5,
  };
}

describe('TvExceptions — estado vazio', () => {
  it('confirma explicitamente que não há alertas (nunca área em branco)', () => {
    const empty: TvExceptionsResult = { items: [], overflowCount: 0, totalCount: 0 };
    render(<TvExceptions exceptions={empty} />);
    expect(screen.getByTestId('tv-exceptions-empty')).toBeInTheDocument();
    expect(
      screen.getByText('Nenhum alerta — tudo dentro do normal'),
    ).toBeInTheDocument();
    // header permanece, contagem oculta em 0
    expect(screen.getByText('EXCEÇÕES')).toBeInTheDocument();
  });
});

describe('TvExceptions — lista e overflow', () => {
  it('renderiza máx 7 linhas + slot "+N outros alertas"', () => {
    const result: TvExceptionsResult = {
      items: Array.from({ length: 7 }, (_, i) => stockOut(i + 1)),
      overflowCount: 3,
      totalCount: 10,
    };
    render(<TvExceptions exceptions={result} />);
    expect(screen.getAllByTestId('tv-exception-row')).toHaveLength(7);
    expect(screen.getByTestId('tv-exceptions-overflow')).toHaveTextContent(
      '+ 3 outros alertas',
    );
    // contagem total no header
    expect(screen.getByText('10')).toBeInTheDocument();
  });

  it('linha de ruptura mostra produto — loja e valor "0 un"', () => {
    const result: TvExceptionsResult = {
      items: [stockOut(1)],
      overflowCount: 0,
      totalCount: 1,
    };
    render(<TvExceptions exceptions={result} />);
    const row = screen.getByTestId('tv-exception-row');
    expect(row).toHaveAttribute('data-severity', 'red');
    expect(row).toHaveTextContent('Produto 1 — Momma Lago Sul');
    expect(row).toHaveTextContent('0 un');
  });
});

import { render, screen } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router-dom';
import TvMetasPage from './TvMetas.page';

// Override do mock global: lojas com fábrica (deve ser filtrada da grade)
// e uma meta pré-existente pra segunda-feira da Asa Sul.
vi.mock('@/integrations/supabase/client', () => {
  const makeBuilder = (result: { data: unknown; error: null }) => {
    const b: Record<string, unknown> = {};
    for (const m of ['select', 'eq', 'order', 'limit', 'upsert']) {
      b[m] = vi.fn().mockReturnValue(b);
    }
    b.then = (
      resolve: (v: { data: unknown; error: null }) => unknown,
      reject?: (e: unknown) => unknown,
    ) => Promise.resolve(result).then(resolve, reject);
    return b;
  };
  return {
    supabase: {
      from: vi.fn((table: string) => {
        if (table === 'lojas') {
          return makeBuilder({
            data: [
              { id: 1, nome: 'Fábrica', tipo: 'Fabrica' },
              { id: 2, nome: 'Momma Asa Sul', tipo: 'Loja' },
              { id: 5, nome: 'Momma Águas Claras', tipo: 'loja' },
            ],
            error: null,
          });
        }
        return makeBuilder({
          data: [{ loja_id: 2, dia_semana: 1, valor_meta: 4000 }],
          error: null,
        });
      }),
    },
  };
});

function renderPage() {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  return render(
    <QueryClientProvider client={client}>
      <MemoryRouter>
        <TvMetasPage />
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

describe('TvMetasPage — grade lojas × dias da semana', () => {
  it('renderiza colunas dom–sáb e uma linha por loja de venda (sem fábrica)', async () => {
    renderPage();
    // Lojas de venda viram linhas; fábrica é filtrada
    expect(await screen.findByText('Momma Asa Sul')).toBeInTheDocument();
    expect(screen.getByText('Momma Águas Claras')).toBeInTheDocument();
    expect(screen.queryByText('Fábrica')).not.toBeInTheDocument();
    expect(screen.getAllByTestId('tv-metas-row')).toHaveLength(2);

    // Cabeçalhos dom–sáb
    for (const dia of ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb']) {
      expect(screen.getByText(dia)).toBeInTheDocument();
    }

    // 2 lojas × 7 dias = 14 inputs; meta existente pré-preenchida
    const inputs = screen.getAllByRole('spinbutton');
    expect(inputs).toHaveLength(14);
    expect(
      screen.getByLabelText('Meta de Momma Asa Sul — Seg'),
    ).toHaveDisplayValue('4000');
  });

  it('expõe ação de salvar e botão de voltar para /tv', async () => {
    renderPage();
    await screen.findByText('Momma Asa Sul');
    expect(
      screen.getByRole('button', { name: /salvar metas/i }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole('button', { name: /voltar para o painel tv/i }),
    ).toBeInTheDocument();
  });
});

